#include <iostream>
#include <vector>

int main()
{
    std::vector<int> scores = {72, 85, 90};
    scores.push_back(64);
    int total = 0;
    for (int s : scores) total += s;
    std::cout << scores.size() << " scores, total " << total << "\n";
    std::cout << "first " << scores[0] << ", last " << scores.back() << "\n";
    return 0;
}

